cs=Cs(CS_ARCH_X86,CS_MODE_64);instructions={}
for name in ['capture.json','capture-2.json','capture-3.json']:
 for f in load(HERE/name)['functions']:
  a=int(f['addr'],16);b=bytes(int(x,16) for x in f['idaBytes'].split())
  for row in f['disassembly']['asm']['lines']:
   pc=int(row['addr'],16);i=next(cs.disasm(b[pc-a:],pc,count=1));instructions[f'{pc-0x140000000:06x}']=[i.mnemonic,i.op_str]
